# Type-specific configuration switch
function Get-TypeConfig {
    param([string] $Type)

    switch ($Type) {
        'Package' {
            @{
                GetCommand    = { Get-AppxProvisionedPackage -Online }
                FilterCommand = { param($item, $sel) $item.DisplayName -eq $sel }
                RemoveCommand = { param($item) $item | Remove-AppxProvisionedPackage -AllUsers -Online -ErrorAction Continue }
                NeedsReboot   = $false
            }
        }
        'Capability' {
            @{
                GetCommand    = { Get-WindowsCapability -Online | Where-Object { $_.State -notin @('NotPresent','Removed') } }
                FilterCommand = { param($item, $sel) ($item.Name -split '~')[0] -eq $sel }
                RemoveCommand = { param($item) $item | Remove-WindowsCapability -Online -ErrorAction Continue }
                NeedsReboot   = $false
            }
        }
        'Feature' {
            @{
                GetCommand    = { Get-WindowsOptionalFeature -Online | Where-Object { $_.State -notin @('Disabled','DisabledWithPayloadRemoved') } }
                FilterCommand = { param($item, $sel) $item.FeatureName -eq $sel }
                RemoveCommand = { param($item) $item | Disable-WindowsOptionalFeature -Online -Remove -NoRestart -ErrorAction Continue }
                NeedsReboot   = $true
            }
        }
    }
}

# Generic remove function
function Invoke-RemoveItems {
    param(
        [string]   $Type,
        [string[]] $Selectors
    )

    $config = Get-TypeConfig -Type $Type

    foreach ($selector in $Selectors) {
        $result = [ordered]@{ Type = $Type; Selector = $selector }

        # Refresh $installed per selector
        $installed = & $config.GetCommand

        # Filter with explicit parameter (no closure scope)
        $found = $installed | Where-Object { & $config.FilterCommand $_ $selector }

        if ($found) {
            # Vorher/Nachher statt $?
            $before = @($found).Count
            $found | ForEach-Object { & $config.RemoveCommand $_ }

            $installedAfter = & $config.GetCommand
            $after = @($installedAfter | Where-Object { & $config.FilterCommand $_ $selector }).Count

            if ($after -lt $before) {
                $result.Message = "$Type removed."
                if ($config.NeedsReboot) { $global:PendingReboot = $true }
            } else {
                $result.Message = "$Type not removed."
                $result.Error = if ($Error[0]) { $Error[0].ToString() } else { $null }
            }
        } else {
            $result.Message = "$Type not installed."
        }

        $result | ConvertTo-Json -Depth 3 -Compress
    }
}

# Removal execution
& {
    Invoke-RemoveItems -Type 'Package'    -Selectors $packages
    Invoke-RemoveItems -Type 'Capability' -Selectors $capabilities
    Invoke-RemoveItems -Type 'Feature'    -Selectors $features

    if ($global:PendingReboot) {
        [ordered]@{
            Type    = 'System'
            Message = 'NOTE: Reboot required for full feature removal.'
        } | ConvertTo-Json -Compress
    }

} *>&1 | Out-String -Width 1KB -Stream >> $logfile

