    {
        $names = @(
            'ContentDeliveryAllowed',
            'FeatureManagementEnabled',
            'OEMPreInstalledAppsEnabled',
            'PreInstalledAppsEnabled',
            'PreInstalledAppsEverEnabled',
            'SilentInstalledAppsEnabled',
            'SoftLandingEnabled',
            'SubscribedContentEnabled',
            'SubscribedContent-310093Enabled',
            'SubscribedContent-338387Enabled',
            'SubscribedContent-338388Enabled',
            'SubscribedContent-338389Enabled',
            'SubscribedContent-338393Enabled',
            'SubscribedContent-353694Enabled',
            'SubscribedContent-353696Enabled',
            'SubscribedContent-353698Enabled',
            'SystemPaneSuggestionsEnabled'
        );

        foreach ($name in $names) {
            reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" `
                /v $name /t REG_DWORD /d 0 /f;
        }
    }
    {
        foreach ($root in 'Registry::HKU\.DEFAULT', 'Registry::HKU\DefaultUser') {
            Set-ItemProperty -LiteralPath "$root\Control Panel\Keyboard" `
                -Name InitialKeyboardIndicators -Type String -Value 2 -Force;
        }
    }
    {
        $params = @{
            LiteralPath = 'Registry::HKU\DefaultUser\Control Panel\Mouse'
            Type        = 'String'
            Value       = 0
            Force       = $true
        };

        Set-ItemProperty @params -Name MouseSpeed;
        Set-ItemProperty @params -Name MouseThreshold1;
        Set-ItemProperty @params -Name MouseThreshold2;
    }
    {
        reg.exe import "C:\Windows\Setup\Scripts\DefaultUser.reg";
    }
    {
        & 'C:\Windows\Setup\Scripts\DefaultUser.cmd';
    }
    {
        reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" `
            /v UnattendedSetup `
            /t REG_SZ `
            /d "powershell.exe -WindowStyle Hidden -ExecutionPolicy Bypass -NoProfile -File `"C:\Windows\Setup\Scripts\UserRunOnce.ps1`"" `
            /f;
    }
);
