$scripts = @(
    {
        Get-AppxPackage -Name 'Microsoft.Windows.Ai.Copilot.Provider' | Remove-AppxPackage;
    }
    {
		# Remove only known problematic reparse points, not all symlinks blindly
		$knownJunctions = @(
			"$env:USERPROFILE\Application Data",
			"$env:USERPROFILE\Cookies",
			"$env:USERPROFILE\Local Settings",
			"$env:USERPROFILE\My Documents",
			"$env:USERPROFILE\NetHood",
			"$env:USERPROFILE\PrintHood",
			"$env:USERPROFILE\Recent",
			"$env:USERPROFILE\SendTo",
			"$env:USERPROFILE\Start Menu",
			"$env:USERPROFILE\Templates"
		)
		foreach ($path in $knownJunctions) {
			if (Test-Path $path) {
				$item = Get-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
				if ($item.Attributes.HasFlag([System.IO.FileAttributes]::ReparsePoint)) {
					Remove-Item -LiteralPath $path -Force -Recurse -ErrorAction SilentlyContinue -Verbose
				}
			}
		}
    }
    {
        Remove-Item -LiteralPath "$env:USERPROFILE\Desktop\Microsoft Edge.lnk" -ErrorAction SilentlyContinue -Verbose;
    }
    {
        New-Item 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Force | Out-Null;

        $classic = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu';
        $new     = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel';

        foreach ($id in @(
            '{5399e694-6ce5-4d6c-8fce-1d8870fdcba0}',
            '{b4bfcc3a-db2c-424c-b029-7fe99a87c641}',
            '{a8cdff1c-4878-43be-b5fd-f8091c1c60d0}',
            '{374de290-123f-4565-9164-39c4925e467b}',
            '{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}',
            '{f874310e-b6b7-47dc-bc84-b9e6b38f5903}',
            '{1cf1260c-4dd0-4ebb-811f-33c572699fde}',
            '{f02c1a0d-be21-4350-88b0-7367fc96ef3c}',
            '{3add1653-eb32-4cb0-bbd7-dfa0abb5acca}',
            '{20d04fe0-3aea-1069-a2d8-08002b30309d}',
            '{59031a47-3f72-44a7-89c5-5595fe6b30ee}',
            '{a0953c92-50dc-43bf-be83-3742fed03c9c}'
        )) {
            Set-ItemProperty -Path $classic -Name $id -Type DWord -Value 1;
        }

        Set-ItemProperty -Path $classic -Name '{645ff040-5081-101b-9f08-00aa002f954e}' -Type DWord -Value 0;

        New-Item $new -Force | Out-Null;

        foreach ($id in @(
            '{5399e694-6ce5-4d6c-8fce-1d8870fdcba0}',
            '{b4bfcc3a-db2c-424c-b029-7fe99a87c641}',
            '{a8cdff1c-4878-43be-b5fd-f8091c1c60d0}',
            '{374de290-123f-4565-9164-39c4925e467b}',
            '{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}',
            '{f874310e-b6b7-47dc-bc84-b9e6b38f5903}',
            '{1cf1260c-4dd0-4ebb-811f-33c572699fde}',
