            '{3add1653-eb32-4cb0-bbd7-dfa0abb5acca}',
            '{20d04fe0-3aea-1069-a2d8-08002b30309d}',
            '{59031a47-3f72-44a7-89c5-5595fe6b30ee}',
            '{a0953c92-50dc-43bf-be83-3742fed03c9c}'
        )) {
            Set-ItemProperty -Path $new -Name $id -Type DWord -Value 1;
        }

        Set-ItemProperty -Path $new -Name '{645ff040-5081-101b-9f08-00aa002f954e}' -Type DWord -Value 0;
    }
    {
        reg.exe import "C:\Windows\Setup\Scripts\UserRunOnce.reg";
    }
    {
        & 'C:\Windows\Setup\Scripts\UserRunOnce.cmd';
    }
    {
        Get-Process explorer -ErrorAction SilentlyContinue |
            Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId } |
            Stop-Process -Force;
